import{_ as a,o,c as t,ag as r}from"./chunks/framework.CrXGS008.js";const f=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function s(c,e,d,i,h,l){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="the-console-says-you-lack-the-required-entitlement" tabindex="-1">The console says <code>You lack the required entitlement</code> <a class="header-anchor" href="#the-console-says-you-lack-the-required-entitlement" aria-label="Permalink to &quot;The console says `You lack the required entitlement`&quot;">​</a></h2><p>The script is not linked to the Cfx.re account that owns your server license key. Check in <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> that the account which bought the script is the one that created the key in <code>sv_licenseKey</code>. Entitlements are read when the server starts: restart the whole server after a new purchase, a <code>restart</code> of the resource is not enough.</p><h2 id="could-not-find-dependency-nay-lib-for-resource-nay-car-wash" tabindex="-1"><code>Could not find dependency nay_lib for resource nay_car_wash</code> <a class="header-anchor" href="#could-not-find-dependency-nay-lib-for-resource-nay-car-wash" aria-label="Permalink to &quot;`Could not find dependency nay_lib for resource nay_car_wash`&quot;">​</a></h2><p><code>nay_lib</code> must start before every Nayretis script, and both folders must be in your <code>resources</code> folder. Check the order of the <code>ensure</code> lines in <code>server.cfg</code>: <code>ensure nay_lib</code> comes first, after your framework, inventory and target resources.</p><h2 id="no-supported-framework-detected" tabindex="-1"><code>No supported framework detected</code> <a class="header-anchor" href="#no-supported-framework-detected" aria-label="Permalink to &quot;`No supported framework detected`&quot;">​</a></h2><p>Start <code>nay_lib</code> after your framework resource. If detection still fails, force it in <code>server.cfg</code>, for example <code>setr nay:framework &quot;esx&quot;</code>. The values are listed on the <a href="/bridge/">Bridge</a> page. Running a framework that is not supported? Write a <a href="/bridge/custom">custom adapter</a>.</p><h2 id="database-errors-on-start" tabindex="-1">Database errors on start <a class="header-anchor" href="#database-errors-on-start" aria-label="Permalink to &quot;Database errors on start&quot;">​</a></h2><p><code>oxmysql</code> must be started before <code>nay_lib</code> and connected to your database (<code>mysql_connection_string</code> in <code>server.cfg</code>). The tables are created on the first start, so the database user needs the right to create tables.</p><h2 id="how-do-i-change-the-language" tabindex="-1">How do I change the language? <a class="header-anchor" href="#how-do-i-change-the-language" aria-label="Permalink to &quot;How do I change the language?&quot;">​</a></h2><p>Open <code>/nay</code>, then <strong>Nayretis</strong>, then <strong>Language</strong>. English, French, Spanish, Portuguese, Polish and German are included, and the language applies to every Nayretis script. <code>setr nay:locale &quot;fr&quot;</code> in <code>server.cfg</code> sets the language used before anyone changes it in game.</p><h2 id="which-files-can-i-edit" tabindex="-1">Which files can I edit? <a class="header-anchor" href="#which-files-can-i-edit" aria-label="Permalink to &quot;Which files can I edit?&quot;">​</a></h2><ul><li><code>config.lua</code> of each script: optional starting values. They apply until a setting is changed in <code>/nay</code>, and <strong>Reset</strong> goes back to them.</li><li><code>locales/*.json</code>: every text shown to players.</li><li><code>nay_lib/bridge/custom.lua</code>: your own framework adapter.</li></ul><p>The rest of the code is protected by Cfx escrow.</p><h2 id="does-nay-lib-connect-to-anything" tabindex="-1">Does nay_lib connect to anything? <a class="header-anchor" href="#does-nay-lib-connect-to-anything" aria-label="Permalink to &quot;Does nay_lib connect to anything?&quot;">​</a></h2><p>At start, <code>nay_lib</code> reads a public version file (<code>https://versions.nayretis.com/versions.json</code>) and prints in the console when an update is available. Turn it off with <code>set nay:versionCheck false</code>. Nothing else leaves your server unless you turn on the <a href="/nay-lib/api">HTTP API</a> or add <a href="/nay-lib/webhooks">webhooks</a>.</p><h2 id="where-do-i-get-help" tabindex="-1">Where do I get help? <a class="header-anchor" href="#where-do-i-get-help" aria-label="Permalink to &quot;Where do I get help?&quot;">​</a></h2><p>Open a post in <code>#support</code> on the <a href="https://discord.gg/HqNyFsDBmw" target="_blank" rel="noreferrer">Nayretis Discord</a>, one post per issue, with the script and its version, your framework, inventory and target, and the server console and F8 errors.</p>',18)])])}const p=a(n,[["render",s]]);export{f as __pageData,p as default};
